package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="certificates") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class Certificate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id",nullable=false) Student student; @Column(nullable=false,length=40) String certificateType; @Column(nullable=false,unique=true,length=50) String certificateNumber; @Column(nullable=false,columnDefinition="TEXT") String content; @Column(nullable=false) LocalDate issueDate; @Column(name="created_at",updatable=false) LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();if(issueDate==null)issueDate=LocalDate.now();} }
